_CONDITION_SOURCE = '# Frozen paid-data predictor; controls and recorded history only.\n_PROGRAM = (\'ge\', None, None, 0, ((\'feature\', None, \'public_51\', 0, ()), (\'const\', 0.5, None, 0, ())))\n\ndef _eval(node, features, history):\n    op, value, name, lag, children = node\n    if op == "const":\n        return float(value)\n    if op == "feature":\n        return float(features[name])\n    if op == "available":\n        return float(len(history) >= lag)\n    if op == "lag":\n        if len(history) < lag:\n            raise ValueError("insufficient control history")\n        return float(history[-lag][name])\n    if op == "if":\n        return _eval(children[1 if _eval(children[0], features, history) else 2], features, history)\n    if op == "object_sum":\n        return sum(_eval(child, features, history) for child in children)\n    if op == "accumulate":\n        state = _eval(children[1], features, history)\n        for index, point in enumerate(history):\n            state = value * state + _eval(children[0], point, history[:index])\n        return value * state + _eval(children[0], features, history)\n    if op == "event_delta":\n        if len(history) < lag:\n            return 0.0\n        index = len(history) - lag\n        return (_eval(children[0], features, history)\n                - _eval(children[0], history[index], history[:index]))\n    if op == "window_sum":\n        start = max(0, len(history) - lag + 1)\n        return _eval(children[0], features, history) + sum(\n            _eval(children[0], history[index], history[:index])\n            for index in range(start, len(history)))\n    left = _eval(children[0], features, history)\n    if op == "abs":\n        return abs(left)\n    if op == "not":\n        return float(not left)\n    right = _eval(children[1], features, history)\n    if op == "add":\n        return left + right\n    if op == "sub":\n        return left - right\n    if op == "mul":\n        return left * right\n    if op == "min":\n        return min(left, right)\n    if op == "max":\n        return max(left, right)\n    if op == "ge":\n        return float(left >= right)\n    if op == "lt":\n        return float(left < right)\n    if op == "and":\n        return float(bool(left) and bool(right))\n    if op == "or":\n        return float(bool(left) or bool(right))\n    raise ValueError("unsupported operator: " + op)\n\ndef predict(row):\n    features = row["features"] if isinstance(row, dict) else row.features\n    history = row["history"] if isinstance(row, dict) else row.history\n    return float(_eval(_PROGRAM, features, history))\n'
_CONDITION_FEATURES = ['public_51']

def _condition(memory):
    if (memory.get('method_condition_support') or {}).get('can_apply') is not True:
        return None
    features = memory.get('method_condition_features') or {}
    if any(name not in features or features[name] is None
           or not isinstance(features[name], (int, float))
           or not math.isfinite(features[name]) for name in _CONDITION_FEATURES):
        return None
    namespace = {}
    exec(_CONDITION_SOURCE, namespace)
    return bool(namespace['predict']({'features': features, 'history': []}))

def select_actions(public_spec, observations, memory):
    path = memory.get('ordinary_method_path')
    if not path:
        return {'stop': {'status': 'author_work_request', 'request': {
            'type': 'AuthorWorkRequest', 'reason': 'ordinary_method_path_required',
            'required': ['frozen ordinary method manifest binding']}}}
    namespace = {'__file__': path}
    exec(compile(Path(path).read_text(encoding='utf-8'), path, 'exec'), namespace)
    if 'select_research_segment' not in namespace:
        return {'stop': {'status': 'author_work_request', 'request': {
            'type': 'AuthorWorkRequest', 'reason': 'ordinary_method_selection_adapter_required',
            'required': ['current ordinary source with the registered finite selection consumer'],
            'ordinary_method_path': path}}}
    plan = memory.get('research_selection_plan', _FROZEN_PLAN)
    return namespace['select_research_segment'](public_spec, observations, memory,
        plan=plan, ordinary_select_actions=namespace['select_actions'],
        condition=_condition if _CONDITION_SOURCE is not None else None)
